function request(method='GET',cookie='',query='',body,extra={}){return new Request(base+'/api/fans/cumpleanos'+query,{method,headers:{cookie,origin:base,'cf-connecting-ip':'192.0.2.1',...extra},...(body?{body}:{})});}
async function browser(){const response=await m.handleBirthdayApi(request());assert.equal(response.status,200);const cookie=response.headers.get('set-cookie').split(';')[0];return {cookie,config:await response.json(),headers:response.headers};}
function form(id=crypto.randomUUID(),photo=png,{token='fixture-human',filename='portrait.png',fileType='image/png'}={}){const data=new FormData();data.set('id',id);data.set('photo',new File([photo],filename,{type:fileType}));data.set('turnstileToken',token);return data;}
async function upload(cookie,{id=crypto.randomUUID(),photo=png,extra={},fields={}}={}){const response=await m.handleBirthdayApi(request('POST',cookie,'',form(id,photo,fields),extra));return {status:response.status,body:await response.json(),headers:response.headers,id};}
async function inspect(cookie,id,method='GET',tail=''){const response=await m.handleBirthdayApi(request(method,cookie,'?id='+id+tail));return {status:response.status,body:await response.json(),headers:response.headers};}
async function internalAccess(cookie,{code='4826',method='POST',body,extra={}}={}){const response=await m.handleBirthdayApi(request(method,cookie,'?internal=1',method==='POST'?(body??JSON.stringify({code})):undefined,{'content-type':'application/json',...extra}));return {status:response.status,body:await response.json(),headers:response.headers,cookie:response.headers.getSetCookie().find(value=>value.startsWith('__Host-jac_fan_internal='))?.split(';')[0]??''};}
async function resetQuota(cookie,{id=crypto.randomUUID(),body,extra={}}={}){const response=await m.handleBirthdayApi(request('POST',cookie,'?internal-reset=1',body??JSON.stringify({id}),{'content-type':'application/json',...extra}));return {status:response.status,body:await response.json(),headers:response.headers,id};}
async function config(cookie){return (await m.handleBirthdayApi(request('GET',cookie))).json();}
