test('one cron starts two generations together and waits for the remaining job after another finalizer fails',async()=>{
 const b=await browser(),failed=await upload(b.cookie,{photo:markedPhoto(1)}),ready=await upload(b.cookie,{photo:markedPhoto(2)}),entered=deferred(),fail=deferred(),finish=deferred(),finalizerFailed=deferred();let arrivals=0,settled=false;
 generateHook=async bytes=>{if(++arrivals===2)entered.resolve();if(bytes[bytes.length-1]===1){await fail.promise;throw Error('Synthetic provider outcome is uncertain.');}await finish.promise;return png;};let injected=false;onRun=async q=>{if(!injected&&q.text.includes("SET claim='' WHERE id=? AND claim=?")&&q.args[0]===failed.id){injected=true;finalizerFailed.resolve();throw Error('Synthetic failed finalizer acknowledgement.');}};
 const processing=m.processBirthdayJobs().then(()=>{settled=true;},error=>{settled=true;throw error;});await entered.promise;assert.equal(counts.generate,2);assert.equal(sql.prepare("SELECT count(*) n FROM jac_fan_birthday_jobs WHERE status='processing'").get().n,2);fail.resolve();await finalizerFailed.promise;await new Promise(resolve=>setImmediate(resolve));assert.equal(settled,false,'A rejected job must not end the cron while another paid call is still running.');finish.resolve();await processing;assert.equal(dbJob(failed.id).status,'uncertain');assert.equal(dbJob(ready.id).status,'ready');onRun=null;await m.processBirthdayJobs();assert.equal(counts.generate,2,'Neither completed nor uncertain requests may be generated again.');
});
